// SetPCF of the receitas to the related item.
// Sets o.R.PCF to related.
// Adds o to related.R.PCFReceitas.
func (o *Receitas) SetPCF(ctx context.Context, exec boil.ContextExecutor, insert bool, related *PlanoContasFinanceiro) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE `receitas` SET %s WHERE %s",
		strmangle.SetParamNames("`", "`", 0, []string{"pcf_id"}),
		strmangle.WhereClause("`", "`", 0, receitasPrimaryKeyColumns),
	)
	values := []interface{}{related.PCFID, o.RecID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	o.PCFID = related.PCFID
	if o.R == nil {
		o.R = &receitasR{
			PCF: related,
		}
	} else {
		o.R.PCF = related
	}

	if related.R == nil {
		related.R = &planoContasFinanceiroR{
			PCFReceitas: ReceitasSlice{o},
		}
	} else {
		related.R.PCFReceitas = append(related.R.PCFReceitas, o)
	}

	return nil
}

// AddRecContratoEntidadeTipos adds the given related objects to the existing relationships
// of the receitas, optionally inserting them as new records.
// Appends related to o.R.RecContratoEntidadeTipos.
// Sets related.R.Rec appropriately.
func (o *Receitas) AddRecContratoEntidadeTipos(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*ContratoEntidadeTipo) error {
	var err error
	for _, rel := range related {
		if insert {
			queries.Assign(&rel.RecID, o.RecID)
			if err = rel.Insert(ctx, exec, boil.Infer()); err != nil {
				return errors.Wrap(err, "failed to insert into foreign table")
			}
		} else {
			updateQuery := fmt.Sprintf(
				"UPDATE `contrato_entidade_tipo` SET %s WHERE %s",
				strmangle.SetParamNames("`", "`", 0, []string{"rec_id"}),
				strmangle.WhereClause("`", "`", 0, contratoEntidadeTipoPrimaryKeyColumns),
			)
			values := []interface{}{o.RecID, rel.CetID}

			if boil.IsDebug(ctx) {
				writer := boil.DebugWriterFrom(ctx)
				fmt.Fprintln(writer, updateQuery)
				fmt.Fprintln(writer, values)
			}
			if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
				return errors.Wrap(err, "failed to update foreign table")
			}

			queries.Assign(&rel.RecID, o.RecID)
		}
	}

	if o.R == nil {
		o.R = &receitasR{
			RecContratoEntidadeTipos: related,
		}
	} else {
		o.R.RecContratoEntidadeTipos = append(o.R.RecContratoEntidadeTipos, related...)
	}

	for _, rel := range related {
		if rel.R == nil {
			rel.R = &contratoEntidadeTipoR{
				Rec: o,
			}
		} else {
			rel.R.Rec = o
		}
	}
	return nil
}

